SELECT DISTINCTROW First([Имена-итогов].NAME) AS NAME, [Рабочий(станции)].OBL, [Рабочий(станции)].OES, [Имена-итогов].NUMB1, [Рабочий(станции)].YEAR, Sum([Рабочий(станции)].NUST) AS NUST, Sum([Рабочий(станции)].E) AS E, Sum([Рабочий(станции)].EOTP) AS EOTP, IIf([EOTP]>0,[EUST]/[EOTP]*1000,0) AS EURT, Sum([Рабочий(станции)].EUST) AS EUST, Sum([Рабочий(станции)].Q) AS Q, IIf([Q]>0,[TUST]/[Q]*1000,0) AS TURT, Sum([Рабочий(станции)].TUST) AS TUST, Sum([Рабочий(станции)].B) AS B, Sum([Рабочий(станции)].GAZ) AS GAZ, Sum([Рабочий(станции)].MAZUT) AS MAZUT, Sum([Рабочий(станции)].TORF) AS TORF, Sum([Рабочий(станции)].SLAN) AS SLAN, Sum([Рабочий(станции)].GTT) AS GTT, Sum([Рабочий(станции)].PROCH) AS PROCH, Sum([Рабочий(станции)].UGOL) AS UGOL, Sum([Рабочий(станции)].DON) AS DON, Sum([Рабочий(станции)].PODM) AS PODM, Sum([Рабочий(станции)].PECH) AS PECH, Sum([Рабочий(станции)].ARKT) AS ARKT, Sum([Рабочий(станции)].KUZN) AS KUZN, Sum([Рабочий(станции)].URAL) AS URAL, Sum([Рабочий(станции)].BASHK) AS BASHK, Sum([Рабочий(станции)].EKIB) AS EKIB, Sum([Рабочий(станции)].KARAG) AS KARAG, Sum([Рабочий(станции)].KAN) AS KAN, Sum([Рабочий(станции)].IRKUT) AS IRKUT, Sum([Рабочий(станции)].HAK) AS HAK, Sum([Рабочий(станции)].TUV) AS TUV, Sum([Рабочий(станции)].BUR) AS BUR, Sum([Рабочий(станции)].CHIT) AS CHIT, Sum([Рабочий(станции)].NER) AS NER, Sum([Рабочий(станции)].RAICH) AS RAICH, Sum([Рабочий(станции)].URG) AS URG, Sum([Рабочий(станции)].PRIM) AS PRIM, Sum([Рабочий(станции)].LUCH) AS LUCH, Sum([Рабочий(станции)].MAG) AS MAG, Sum([Рабочий(станции)].SAH) AS SAH, Sum([Рабочий(станции)].QOTR) AS QOTR, Sum([Рабочий(станции)].EWTP) AS EWTP, Sum([Рабочий(станции)].NT) AS NT, First([Рабочий(станции)].OES) AS OES, Sum([Рабочий(доп_угли)].nazar) AS nazar, Sum([Рабочий(доп_угли)].ibor) AS ibor, Sum([Рабочий(доп_угли)].berez) AS berez, Sum([Рабочий(доп_угли)].gusin) AS gusin, Sum([Рабочий(доп_угли)].tugn) AS tugn, Sum([Рабочий(доп_угли)].azey) AS azey, Sum([Рабочий(доп_угли)].cher) AS cher, Sum([Рабочий(доп_угли)].vork) AS vork, Sum([Рабочий(доп_угли)].int) AS [int], Sum([Рабочий(доп_угли)].sver) AS sver, Sum([Рабочий(доп_угли)].chel) AS chel, Sum([Рабочий(доп_угли)].kizel) AS kizel
FROM ([Рабочий(станции)] LEFT JOIN [Имена-итогов] ON [Рабочий(станции)].VED=[Имена-итогов].VED) LEFT JOIN [Рабочий(доп_угли)] ON ([Рабочий(станции)].YEAR=[Рабочий(доп_угли)].YEAR) AND ([Рабочий(станции)].NUMB1120=[Рабочий(доп_угли)].NUMB1120)
WHERE ((([Рабочий(станции)].VED)>0))
GROUP BY [Рабочий(станции)].OBL, [Рабочий(станции)].OES, [Имена-итогов].NUMB1, [Рабочий(станции)].YEAR;
